package com.techgenius.tvoslauncher;
import java.util.*;
public final class GlobalNewsDataTest {
 static int checks;static void check(boolean ok,String reason){checks++;if(!ok)throw new AssertionError(reason);}
 public static void main(String[] args)throws Exception{
  long now=GlobalNewsData.date("Wed, 04 Nov 2026 02:00:00 GMT");check(now>0,"RSS date");check(now==GlobalNewsData.date("2026-11-04T05:00:00+03:00"),"Riyadh date");check(GlobalNewsData.date("unknown")==0,"unknown dates stay unknown");check(GlobalNewsData.age(0,now).contains("غير متاح"),"No invented publication age");
  check((GlobalNewsData.classify("الرياضة وكرة القدم")&(1<<1))==0,"Sports is not Riyadh");check((GlobalNewsData.classify("علم الرياضيات")&(1<<4))==0,"Math is not sport");check((GlobalNewsData.classify("قمة الرياض في السعودية")&2)!=0,"Saudi classification");check((GlobalNewsData.classify("تطوير الذكاء الاصطناعي")&4)!=0,"Technology");check((GlobalNewsData.classify("ارتفاع أسعار النفط")&8)!=0,"Economy");
  String xml="<rss xmlns:media='http://search.yahoo.com/mrss/'><channel><item><title>عاجل | خبر مصدر الاختبار</title><link>https://example.org/story?utm_source=rss&amp;x=1#top</link><pubDate>Wed, 04 Nov 2026 02:00:00 GMT</pubDate><description><![CDATA[<b>ملخص المصدر</b>]]></description><media:thumbnail url='https://example.org/small.jpg' width='320'/><media:content url='https://example.org/full.jpg' type='image/jpeg' width='1200'/></item></channel></rss>";
  List<GlobalNewsData.Story> parsed=GlobalNewsData.parse(xml,"test publisher",0);check(parsed.size()==1,"RSS item");GlobalNewsData.Story s=parsed.get(0);check(s.urgent,"Explicit breaking only");check(s.summary.equals("ملخص المصدر"),"Clean native summary");check(s.image.endsWith("full.jpg"),"High quality source image");check(s.url.equals("https://example.org/story?x=1"),"Canonical link");check(s.published==now,"Publication parsed");
  GlobalNewsData.Story duplicate=GlobalNewsData.Story.from(s.json());duplicate.sections=8;check(GlobalNewsData.merge(Arrays.asList(s,duplicate)).size()==1,"Dedup");check((s.sections&8)!=0,"Merge section membership");
  check(GlobalNewsData.parse("<rss><channel/></rss>","empty",0).isEmpty(),"Valid empty feed");boolean rejected=false;try{GlobalNewsData.parse("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///etc/passwd'>]><rss/>","unsafe",0);}catch(Exception e){rejected=true;}check(rejected,"No external entities");
  check(GlobalNewsData.webUrl("javascript:alert(1)").isEmpty(),"No executable URL");check(GlobalNewsData.webUrl("https://user:password@example.org/x").isEmpty(),"No credential URL");check(GlobalNewsData.clean("<script>x()</script>نص &#1575;").equals("نص ا"),"HTML cleanup");
  List<GlobalNewsData.Story> atom=GlobalNewsData.parse("<feed xmlns='http://www.w3.org/2005/Atom'><entry><title>خبر تقني</title><link href='https://example.org/atom'/><updated>2026-11-04T02:00:00Z</updated><summary>تقنية حديثة</summary></entry></feed>","Atom",2);check(atom.size()==1&&atom.get(0).published==now,"Atom link/date");check(!atom.get(0).urgent,"Do not invent breaking");
  check(GlobalNewsData.photoUrl("https://images.skynewsarabia.com/images/v1/2026/11/04/1902538/95/53/1-1902538.jpg").equals("https://images.skynewsarabia.com/images/v1/2026/11/04/1902538/1600/900/1-1902538.jpg"),"High resolution of the same source image");check(GlobalNewsData.photoUrl("https://example.org/95/53/photo.jpg").equals("https://example.org/95/53/photo.jpg"),"Do not rewrite other image sources");
  List<GlobalNewsData.Story> many=new ArrayList<>();for(int i=0;i<25;i++){GlobalNewsData.Story n=new GlobalNewsData.Story();n.title="خبر "+i;n.url="https://example.org/"+i;n.published=now-i*1000;n.sections=4;many.add(n);}check(GlobalNewsData.select(many,2,now).size()==25,"All list stories are accessible");check(GlobalNewsData.select(many,1,now).isEmpty(),"Category filter");
  for(String file:args){String raw=new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(file)),java.nio.charset.StandardCharsets.UTF_8);List<GlobalNewsData.Story> real=GlobalNewsData.parse(raw,"Live newsroom fixture",0);check(!real.isEmpty(),"Live fixture "+file);for(GlobalNewsData.Story n:real){check(!n.title.isEmpty()&&n.url.startsWith("https://"),"Real source identity");check(n.image.isEmpty()||n.image.startsWith("https://"),"Source photo URL");}}
  System.out.println("GLOBAL_NEWS_DATA_OK: "+checks+" checks");
 }
}
